function validatePaymentAmount(providedAmount: number, requiredAmount: number): void {
  if (providedAmount < requiredAmount) {
    throw new Error(`Insufficient payment: ${providedAmount} < ${requiredAmount}`);
  }
}

export async function processPremiumPayment(
  userId: string,
  payment: PaymentDetails,
  tier: 'premium' | 'enterprise',
  dbClient: DatabaseClient = db
): Promise<void> {
  if (!validatePaymentDetails(payment)) {
    throw new Error('Invalid payment details');
  }

  const requiredAmount = calculateSubscriptionPrice(tier);
  validatePaymentAmount(payment.amount, requiredAmount);

  await chargeCard(payment, requiredAmount, dbClient);
  await upgradeUserSubscription(userId, tier, dbClient);
}
